--
-- Events
--
CREATE DEFINER=`root`@`localhost` EVENT `ev_delete_expired_flights` ON SCHEDULE EVERY 1 MINUTE STARTS '2026-02-18 22:37:16' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
  -- Delete bookings of expired flights
  DELETE b
  FROM bookings b
  JOIN flights f ON b.flight_no = f.flight_no
  WHERE TIMESTAMP(f.flight_date, f.departure_time) < NOW();

  -- Delete expired flights
  DELETE FROM flights
  WHERE TIMESTAMP(flight_date, departure_time) < NOW();
END$$

